function init(p) {
  return { arm: 1 };
}
function decide(s, p, st) {
  if (s.see === 0) st.arm = st.arm % 3 + 1;
  return st.arm;
}

function init(p) {
  return { arm: 1, w: [0.5, 0.5, 0.5], n: [1, 1, 1] };
}
function decide(s, p, st) {
  var i = st.arm - 1, best = 0, k;
  if (s.t > 0) { st.w[i] = p.keep * st.w[i] + s.see; st.n[i] = p.keep * st.n[i] + 1; }
  for (k = 1; k < 3; k++) if (st.w[k] / st.n[k] > st.w[best] / st.n[best]) best = k;
  st.arm = s.rnd() < p.eps ? 1 + Math.floor(3 * s.rnd()) : best + 1;
  return st.arm;
}
